// Deliberately simplified three-trick duel inherited from the original game.
export const JASS_TABLE={id:'jass-table',name:'Mit Sämi am Stammtisch jassen',region:'restaurant',x:-1,z:-.5,range:1.7,jass:true};
export const RESTAURANT_COUNTER={id:'restaurant-menu',name:'Speisekarte im Bergrestaurant',region:'restaurant',x:3,z:1.5,range:1.7,meal:true};
export const MEALS={soup:{name:'Waldsuppe & Alpbrot',price:1400},plate:{name:'Älplerteller',price:1800}};
export const SUITS=['♠','♥','♦','♣'],SUIT_NAMES=['Pik','Herz','Karo','Kreuz'];
export const freshJass=()=>({best:0,runs:0,wins:0,prizeDay:0,active:null});
export const cardSuit=id=>Math.floor(id/9),cardRank=id=>6+id%9;
export const cardLabel=id=>({11:'Bube',12:'Dame',13:'König',14:'Ass'}[cardRank(id)]||cardRank(id))+' '+SUITS[cardSuit(id)];
export function cardStrength(id,lead,trump){const suit=cardSuit(id),rank=cardRank(id);return suit===trump?100+[6,7,8,10,12,13,14,9,11].indexOf(rank):suit===lead?rank:0;}
export function nearTable(s){return s.position.region==='restaurant'&&!s.position.inside&&!s.climbing.checkpoint&&!s.ski.active&&!s.targets.active&&Math.hypot(s.position.x-JASS_TABLE.x,s.position.z-JASS_TABLE.z)<2.4;}
export function legalCards(c){if(!c||c.phase!=='choose')return[];const lead=c.opponent[c.played.length],must=c.hand.some(k=>cardSuit(k)===cardSuit(lead));return c.hand.filter(k=>!must||cardSuit(k)===cardSuit(lead));}
export function wonTrick(card,opponent,trump){return cardStrength(card,cardSuit(opponent),trump)>cardStrength(opponent,cardSuit(opponent),trump);}
export const tricksWon=c=>c.played.filter((card,i)=>wonTrick(card,c.opponent[i],c.trump)).length;
export function startJass(s,random=Math.random){if(!nearTable(s)||s.jass.active)return{ok:false,message:'Gehe zuerst zu Sämi an den Jasstisch.'};const deck=Array.from({length:36},(_,i)=>i);for(let i=35;i>0;i--){const r=random();if(!Number.isFinite(r)||r<0||r>=1)return{ok:false,message:'Die Karten konnten nicht gemischt werden.'};const j=Math.floor(r*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}const r=random();if(!Number.isFinite(r)||r<0||r>=1)return{ok:false,message:'Trumpf konnte nicht bestimmt werden.'};s.jass.active={hand:deck.slice(0,3),opponent:deck.slice(3,6),played:[],trump:Math.floor(r*4),phase:'choose'};return{ok:true};}
export function playJass(s,id){const c=s.jass.active;if(!nearTable(s)||!c||!legalCards(c).includes(id))return{ok:false,message:'Diese Karte ist jetzt nicht erlaubt. Bediene die ausgespielte Farbe, wenn du sie hast.'};c.hand=c.hand.filter(k=>k!==id);c.played.push(id);c.phase='review';return{ok:true};}
export function nextTrick(s){const c=s.jass.active;if(!nearTable(s)||c?.phase!=='review')return{ok:false,message:'Wähle zuerst eine erlaubte Karte.'};c.phase=c.played.length===3?'done':'choose';return{ok:true};}
export function finishJass(s,exchange){const c=s.jass.active;if(!nearTable(s)||c?.phase!=='done')return{ok:false,message:'Die drei Stiche sind noch nicht abgeschlossen.'};const won=tricksWon(c),win=won>=2,reward=win&&s.jass.prizeDay!==s.day?1500:0;const result=exchange(s,{earn:reward,stats:{earned:reward},reason:'challenge',ref:'jass'});if(!result.ok)return result;s.jass.best=Math.max(s.jass.best,won);s.jass.runs=Math.min(1000000,s.jass.runs+1);if(win)s.jass.wins=Math.min(1000000,s.jass.wins+1);if(reward)s.jass.prizeDay=s.day;s.jass.active=null;return{ok:true,win,won,reward};}
export function buyMeal(s,id,exchange){const m=MEALS[id],p=RESTAURANT_COUNTER;if(!m||s.position.region!=='restaurant'||s.position.inside||s.jass.active||Math.hypot(s.position.x-p.x,s.position.z-p.z)>2.4)return{ok:false,message:'Bestelle an der Speisekarte im Bergrestaurant.'};if(s.energy>=100&&s.stamina>=100)return{ok:false,message:'Du bist bereits vollständig erholt.'};const result=exchange(s,{cost:m.price,stats:{spent:m.price},reason:'meal',ref:id});if(!result.ok)return result;s.energy=100;s.stamina=100;return{ok:true,message:m.name+' genossen. Energie und Ausdauer sind voll.'};}
export function validJass(v,s){const obj=o=>o&&typeof o==='object'&&!Array.isArray(o),int=(x,a,b)=>Number.isSafeInteger(x)&&x>=a&&x<=b;if(!obj(v)||!int(v.best,0,3)||!int(v.runs,0,1000000)||!int(v.wins,0,v.runs)||!int(v.prizeDay,0,s.day)||v.prizeDay>0&&v.wins===0)return false;if(v.active===null)return true;const c=v.active;if(!obj(c)||!nearTable(s)||!Array.isArray(c.hand)||!Array.isArray(c.opponent)||!Array.isArray(c.played)||c.opponent.length!==3||c.played.length>3||c.hand.length+c.played.length!==3||!int(c.trump,0,3)||!['choose','review','done'].includes(c.phase)||c.phase==='choose'&&c.played.length===3||c.phase==='review'&&c.played.length===0||c.phase==='done'&&c.played.length!==3)return false;const all=[...c.hand,...c.played,...c.opponent];if(all.length!==6||new Set(all).size!==6||!all.every(k=>int(k,0,35)))return false;for(let i=0;i<c.played.length;i++){const hand=[...c.hand,...c.played.slice(i)],lead=c.opponent[i];if(hand.some(k=>cardSuit(k)===cardSuit(lead))&&cardSuit(c.played[i])!==cardSuit(lead))return false;}return true;}

export function trickReason(card,opponent,trump){const a=cardSuit(card),b=cardSuit(opponent);if(a===b)return a===trump?'Beide Karten sind Trumpf. Es gilt die besondere Trumpfrangfolge.':'Beide Karten haben die ausgespielte Farbe. Die höhere Karte gewinnt.';if(a===trump)return 'Dein Trumpf sticht die ausgespielte Farbe.';if(b===trump)return 'Sämi hat Trumpf ausgespielt. Eine andere Farbe kann ihn nicht stechen.';return 'Deine andere Farbe kann die ausgespielte Farbe nicht stechen.';}
